from fastapi import FastAPI, Depends, HTTPException, Header
from pydantic import BaseModel
import jwt
import os
import json
from typing import Optional

app = FastAPI()

# Public key loaded from mounted volume
PUBLIC_KEY_PATH = os.getenv("JWT_PUBLIC_KEY_PATH", "/etc/keys/public.pem")
ALGORITHM = os.getenv("JWT_ALGORITHM", "RS256")
ISSUER = os.getenv("JWT_ISSUER", "auth.internal.svc")

def load_public_key():
    """Load the RSA public key from the mounted secrets volume"""
    try:
        with open(PUBLIC_KEY_PATH, 'r') as f:
            return f.read()
    except FileNotFoundError:
        raise RuntimeError(f"Public key not found at {PUBLIC_KEY_PATH}")

class TokenPayload(BaseModel):
    sub: str
    role: str
    iss: str
    exp: int

def verify_token(authorization: Optional[str] = Header(None)):
    """Verify JWT token from Authorization header"""
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing authorization header")

    if not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Invalid authorization scheme")

    token = authorization[7:]
    public_key = load_public_key()

    try:
        # Decode the token header to get the algorithm
        unverified_header = jwt.get_unverified_header(token)
        token_algorithm = unverified_header.get("alg", ALGORITHM)

        # Verify token with the algorithm specified in the token header
        payload = jwt.decode(
            token,
            public_key,
            algorithms=[token_algorithm],
            issuer=ISSUER
        )
        return TokenPayload(**payload)
    except jwt.ExpiredSignatureError:
        raise HTTPException(status_code=401, detail="Token expired")
    except jwt.InvalidIssuerError:
        raise HTTPException(status_code=401, detail="Invalid issuer")
    except jwt.InvalidTokenError as e:
        raise HTTPException(status_code=401, detail=f"Invalid token: {str(e)}")

@app.get("/api/v1/admin/users")
async def list_users(token: TokenPayload = Depends(verify_token)):
    """Admin endpoint to list all users"""
    if token.role != "admin":
        raise HTTPException(status_code=403, detail="Insufficient permissions")
    return {"users": [{"id": 1, "name": "alice"}, {"id": 2, "name": "bob"}]}

@app.get("/api/v1/secrets")
async def get_secrets(token: TokenPayload = Depends(verify_token)):
    """Retrieve application secrets - admin only"""
    if token.role != "admin":
        raise HTTPException(status_code=403, detail="Insufficient permissions")
    # Read secrets from mounted volume
    secrets_path = os.getenv("SECRETS_PATH", "/etc/app-secrets/config.json")
    try:
        with open(secrets_path, 'r') as f:
            return json.load(f)
    except FileNotFoundError:
        return {"error": "Secrets not configured"}

@app.get("/api/v1/profile")
async def get_profile(token: TokenPayload = Depends(verify_token)):
    """Get current user profile"""
    return {"sub": token.sub, "role": token.role}

@app.get("/health")
async def health():
    return {"status": "healthy"}

if __name__ == "__main__":
    import uvicorn
    uvicorn.run(app, host="0.0.0.0", port=8080)
